input.sparql:
SELECT ?point ?series WHERE {
  ?z a brick:Zone ; brick:hasIdentifier "Perimeter_mid_ZN_3" .
  ?point brick:isOutputOf ?z ; a brick:Occupancy .
  ?point ref:hasTimeseriesId ?series .
}

SELECT ?z ?label ?point WHERE {
  ?z a brick:Zone .
  OPTIONAL { ?z rdfs:label ?label }
  OPTIONAL { ?z brick:hasIdentifier ?id }
  ?point brick:isOutputOf ?z .
  FILTER (regex(STR(?z), "Perimeter_mid_ZN_3", "i") || regex(STR(?label), "Perimeter", "i"))
}

SELECT ?z ?point ?series WHERE {
  ?point a brick:Occupancy ; ref:hasTimeseriesId ?series .
  ?point brick:isOutputOf ?z .
}

